import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the pricing downstream (euros per unit).
const prices = { A: 10, B: 25.5, BIG: 101, EXACT: 100 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, { method, body: raw ?? (body === undefined ? undefined : JSON.stringify(body)) })
  return { status: res.status, type: res.headers.get('content-type'), body: await res.json() }
}

test('POST /orders creates an order: 201, json, string id, echoed items, total', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const r = await call('POST', '/orders', { items })
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body.items, items)
  assert.equal(r.body.total, 20)
  assert.deepEqual(Object.keys(r.body).sort(), ['id', 'items', 'total'])
})

test('POST /orders ids are sequential', async () => {
  const a = await call('POST', '/orders', { items: [{ sku: 'A', qty: 1 }] })
  const b = await call('POST', '/orders', { items: [{ sku: 'A', qty: 1 }] })
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders total is floored', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'B', qty: 1 }] })
  assert.equal(r.body.total, 25)
})

test('POST /orders no discount at exactly 100', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'EXACT', qty: 1 }] })
  assert.equal(r.body.total, 100)
})

test('POST /orders 10% discount above 100, then floored', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'BIG', qty: 1 }] })
  assert.equal(r.body.total, 90) // 90.9 floored
})

test('POST /orders sums several lines', async () => {
  const r = await call('POST', '/orders', { items: [{ sku: 'A', qty: 3 }, { sku: 'B', qty: 2 }] })
  assert.equal(r.body.total, 81) // 81 -> no discount
})

test('POST /orders with empty items -> 400', async () => {
  const r = await call('POST', '/orders', { items: [] })
  assert.deepEqual([r.status, r.body], [400, { error: 'items required' }])
})

test('POST /orders with missing items, non-array items, invalid JSON, empty body -> 400', async () => {
  for (const r of [
    await call('POST', '/orders', {}),
    await call('POST', '/orders', { items: 'x' }),
    await call('POST', '/orders', undefined, '{not json'),
    await call('POST', '/orders'),
  ]) assert.deepEqual([r.status, r.body], [400, { error: 'items required' }])
})

test('POST /orders with unknown sku / missing qty -> 201 with total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises as null and the order is still created
  const r1 = await call('POST', '/orders', { items: [{ sku: 'NOPE', qty: 1 }] })
  assert.equal(r1.status, 201)
  assert.equal(r1.body.total, null)
  const r2 = await call('POST', '/orders', { items: [{ sku: 'A' }] })
  assert.equal(r2.status, 201)
  assert.equal(r2.body.total, null)
})

test('GET /orders/{id} returns a created order', async () => {
  const created = await call('POST', '/orders', { items: [{ sku: 'A', qty: 4 }] })
  const r = await call('GET', `/orders/${created.body.id}`)
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created.body)
})

test('GET /orders/{id} unknown id -> 200 {error:not found}', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — not-found answered with 200 instead of 404
  const r = await call('GET', '/orders/does-not-exist')
  assert.deepEqual([r.status, r.body], [200, { error: 'not found' }])
})

test('unrouted requests -> 404 {error:no route}', async () => {
  for (const [m, p] of [['GET', '/orders'], ['GET', '/'], ['DELETE', '/orders/1'], ['POST', '/orders/1'], ['PUT', '/orders'], ['GET', '/orders/1/x'], ['GET', '/other']]) {
    const r = await call(m, p)
    assert.deepEqual([m, p, r.status, r.body], [m, p, 404, { error: 'no route' }])
  }
})
